import{_ as i,C as r,c as n,o as d,aa as l,G as t}from"./chunks/framework.ByRpVre_.js";const u=JSON.parse('{"title":"载入 Terra 附属","description":"","frontmatter":{"breadcrumbs":[{"title":"Continue Project","link":"/wiki"},{"title":"Terra","link":"/wiki/Terra"},{"title":"terra-api","link":"/wiki/Terra/terra-api"},{"title":"introduction-to-the-terra-api","link":"/wiki/Terra/terra-api/introduction-to-the-terra-api"},{"title":"载入 Terra 附属","link":"/wiki/Terra/terra-api/introduction-to-the-terra-api/terra-addon-loading"}]},"headers":[],"relativePath":"wiki/Terra/terra-api/introduction-to-the-terra-api/terra-addon-loading.md","filePath":"wiki/Terra/terra-api/introduction-to-the-terra-api/terra-addon-loading.md"}'),p={name:"wiki/Terra/terra-api/introduction-to-the-terra-api/terra-addon-loading.md"};function s(c,a,h,b,_,k){const e=r("NolebaseGitContributors"),o=r("NolebaseGitChangelog");return d(),n("div",null,[a[0]||(a[0]=l('<h1 id="载入-terra-附属" tabindex="-1">载入 Terra 附属 <a class="header-anchor" href="#载入-terra-附属" aria-label="Permalink to &quot;载入 Terra 附属&quot;">​</a></h1><p>本章节解释了 Terra 中的附属载入机制。本页不直接与开发 Terra 附属相关，你可以选择略过。但是，知晓加载过程对开发有利。</p><p>Terra 附属载入过程可以简要分为两个阶段：</p><h2 id="_1-bootstrap-附属载入" tabindex="-1">1. Bootstrap 附属载入 <a class="header-anchor" href="#_1-bootstrap-附属载入" aria-label="Permalink to &quot;1. Bootstrap 附属载入&quot;">​</a></h2><p>Terra 本身能够载入的附属只有 Bootstrap 附属。Bootstrap 附属载入器是一个最小化的附属载入；它会为 <code>Terra-Bootstrap-Addon-Entry-Point</code> 属性检测所有发现的 bootstrap 附属 Jar 的验证文件（位于 <code>addons/bootstrap</code> 文件夹），然后尝试载入并实例化 <a href="https://ci.codemc.io/job/PolyhedralDev/job/Terra/javadoc/com/dfsek/terra/api/addon/bootstrap/BootstrapBaseAddon.html" target="_blank" rel="noreferrer">BootstrapBaseAddon</a> - 实现属性中指定的类。</p><h3 id="bootstrap-附属初始化" tabindex="-1">Bootstrap 附属初始化 <a class="header-anchor" href="#bootstrap-附属初始化" aria-label="Permalink to &quot;Bootstrap 附属初始化&quot;">​</a></h3><p>在所有 bootstrap 附属载入完毕后，<code>#initialize</code> 方法会在各自附属实例上调用。在初始化过程中，bootstrap 附属载入额外的附属，但<em>不会将它们初始化</em>。</p><h2 id="_2-附属初始化" tabindex="-1">2. 附属初始化 <a class="header-anchor" href="#_2-附属初始化" aria-label="Permalink to &quot;2. 附属初始化&quot;">​</a></h2><p>在 bootstrap 附属载入各自的附属之后，新载入的附属必须初始化。</p><h3 id="依赖整理" tabindex="-1">依赖整理 <a class="header-anchor" href="#依赖整理" aria-label="Permalink to &quot;依赖整理&quot;">​</a></h3><p>首先，检查附属的依赖。如果缺失或指定版本无效，或者发生了循环载入情况，都会导致载入失败。</p><p>随后，附属会按载入依赖排列为<a href="https://zh.wikipedia.org/wiki/%E6%9C%89%E5%90%91%E6%97%A0%E7%8E%AF%E5%9B%BE" target="_blank" rel="noreferrer">有向无环图</a>。这个图标会用于决定附属的载入顺序，确保依赖先于对应附属载入。</p><h4 id="初始化" tabindex="-1">初始化 <a class="header-anchor" href="#初始化" aria-label="Permalink to &quot;初始化&quot;">​</a></h4><p>在附属的载入顺序确定之后，附属终于可以开始初始化了。</p><h5 id="依赖注入" tabindex="-1">依赖注入 <a class="header-anchor" href="#依赖注入" aria-label="Permalink to &quot;依赖注入&quot;">​</a></h5><p>Terra 的附属系统利用了一种基于注释的简单注入框架，以此减少引用。当附属全部初始化完毕后，<a href="https://ci.codemc.io/job/PolyhedralDev/job/Terra/javadoc/com/dfsek/terra/api/Platform.html" target="_blank" rel="noreferrer">平台</a>实例会注入到任何有效的注释字段中。</p>',16)),t(e),t(o)])}const T=i(p,[["render",s]]);export{u as __pageData,T as default};
